import{_ as s,o as t,c as e,a3 as i}from"./chunks/framework.BlfGB29P.js";const k=JSON.parse('{"title":"MCP 协议","description":"讲解 MCP 的 Host、Client、Server、生命周期、核心原语、传输和安全边界。","frontmatter":{"title":"MCP 协议","description":"讲解 MCP 的 Host、Client、Server、生命周期、核心原语、传输和安全边界。","framework":"Model Context Protocol","version":"MCP 2025-11-25 stable specification","verified_at":"2026-07-29","source":["https://modelcontextprotocol.io/docs/learn/architecture","https://modelcontextprotocol.io/docs/learn/server-concepts","https://modelcontextprotocol.io/specification/2025-11-25/schema"],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"py-agent/agent/tools-mcp/mcp-protocol.md","filePath":"py-agent/agent/tools-mcp/mcp-protocol.md","lastUpdated":1785311412000}'),n={name:"py-agent/agent/tools-mcp/mcp-protocol.md"};function l(r,a,o,p,h,d){return t(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="mcp-协议" tabindex="-1">MCP 协议 <a class="header-anchor" href="#mcp-协议" aria-label="Permalink to &quot;MCP 协议&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>Model Context Protocol（MCP）标准化了 AI 应用与外部能力之间的发现、读取和调用。它规定通信协议，不规定 Agent 怎样推理，也不替代业务授权。</p><h2 id="_1-参与者" tabindex="-1">1. 参与者 <a class="header-anchor" href="#_1-参与者" aria-label="Permalink to &quot;1. 参与者&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参与者</th><th>职责</th></tr></thead><tbody><tr><td>Host</td><td>AI 应用，管理用户体验、安全策略和多个 Client</td></tr><tr><td>Client</td><td>与一个 Server 保持协议连接</td></tr><tr><td>Server</td><td>暴露 Tools、Resources、Prompts 等能力</td></tr></tbody></table><p>一个 Host 通常为每个 Server 创建独立 Client。Server 可以是本地子进程，也可以是远程服务。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Host</span></span>
<span class="line"><span>  |- MCP Client A &lt;-&gt; Filesystem Server</span></span>
<span class="line"><span>  |- MCP Client B &lt;-&gt; Database Server</span></span>
<span class="line"><span>  \`- MCP Client C &lt;-&gt; Remote SaaS Server</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h2 id="_2-两层协议" tabindex="-1">2. 两层协议 <a class="header-anchor" href="#_2-两层协议" aria-label="Permalink to &quot;2. 两层协议&quot;">​</a></h2><h3 id="_2-1-data-layer" tabindex="-1">2.1 Data Layer <a class="header-anchor" href="#_2-1-data-layer" aria-label="Permalink to &quot;2.1 Data Layer&quot;">​</a></h3><p>基于 JSON-RPC 2.0，定义生命周期、能力协商、请求响应、通知和核心原语。</p><h3 id="_2-2-transport-layer" tabindex="-1">2.2 Transport Layer <a class="header-anchor" href="#_2-2-transport-layer" aria-label="Permalink to &quot;2.2 Transport Layer&quot;">​</a></h3><p>负责连接、消息帧和认证传输。相同数据层可以运行在不同传输上。</p><h2 id="_3-生命周期" tabindex="-1">3. 生命周期 <a class="header-anchor" href="#_3-生命周期" aria-label="Permalink to &quot;3. 生命周期&quot;">​</a></h2><p>MCP 连接先初始化，再进入正常操作：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Client -&gt; initialize(protocolVersion, capabilities, clientInfo)</span></span>
<span class="line"><span>Server -&gt; result(protocolVersion, capabilities, serverInfo)</span></span>
<span class="line"><span>Client -&gt; notifications/initialized</span></span>
<span class="line"><span>Client &lt;-&gt; normal operations</span></span>
<span class="line"><span>connection shutdown</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>初始化解决三件事：协议版本协商、能力发现和身份信息交换。双方不能在未协商能力时假设对方支持某项原语。</p><h2 id="_4-server-原语" tabindex="-1">4. Server 原语 <a class="header-anchor" href="#_4-server-原语" aria-label="Permalink to &quot;4. Server 原语&quot;">​</a></h2><h3 id="_4-1-tools" tabindex="-1">4.1 Tools <a class="header-anchor" href="#_4-1-tools" aria-label="Permalink to &quot;4.1 Tools&quot;">​</a></h3><p>Tools 是可执行动作，由模型或应用请求调用：</p><table tabindex="0"><thead><tr><th>方法</th><th>作用</th></tr></thead><tbody><tr><td><code>tools/list</code></td><td>发现工具和输入 Schema</td></tr><tr><td><code>tools/call</code></td><td>按名称和参数执行工具</td></tr></tbody></table><p>工具可能读写外部系统，因此 Host 仍需做权限、确认和审计。</p><h3 id="_4-2-resources" tabindex="-1">4.2 Resources <a class="header-anchor" href="#_4-2-resources" aria-label="Permalink to &quot;4.2 Resources&quot;">​</a></h3><p>Resources 是可读取的上下文数据，通过 URI 标识，例如文件、数据库 Schema 或文档。</p><table tabindex="0"><thead><tr><th>方法</th><th>作用</th></tr></thead><tbody><tr><td><code>resources/list</code></td><td>发现资源</td></tr><tr><td><code>resources/read</code></td><td>读取资源内容</td></tr><tr><td><code>resources/subscribe</code></td><td>在双方声明支持时订阅变化</td></tr></tbody></table><p>Resource 通常由应用选择是否加入上下文，不等于模型可任意读取所有资源。</p><h3 id="_4-3-prompts" tabindex="-1">4.3 Prompts <a class="header-anchor" href="#_4-3-prompts" aria-label="Permalink to &quot;4.3 Prompts&quot;">​</a></h3><p>Prompts 是用户可选择的参数化模板：</p><table tabindex="0"><thead><tr><th>方法</th><th>作用</th></tr></thead><tbody><tr><td><code>prompts/list</code></td><td>发现模板</td></tr><tr><td><code>prompts/get</code></td><td>根据参数取得消息模板</td></tr></tbody></table><p>Prompt 不是更高权限的系统指令。Host 必须决定怎样展示和组合它。</p><h2 id="_5-client-原语" tabindex="-1">5. Client 原语 <a class="header-anchor" href="#_5-client-原语" aria-label="Permalink to &quot;5. Client 原语&quot;">​</a></h2><p>Server 也可以请求 Client 能力：</p><ul><li>Sampling：请求 Host 使用模型生成内容；</li><li>Elicitation：请求用户补充信息或确认；</li><li>Logging：向 Client 发送日志消息。</li></ul><p>这些能力必须在初始化时声明，并由 Host 执行自己的用户交互和安全政策。</p><h2 id="_6-json-rpc-消息" tabindex="-1">6. JSON-RPC 消息 <a class="header-anchor" href="#_6-json-rpc-消息" aria-label="Permalink to &quot;6. JSON-RPC 消息&quot;">​</a></h2><p>发现工具：</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;jsonrpc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;method&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tools/list&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>调用工具：</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;jsonrpc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;method&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tools/call&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;params&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;weather_current&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;arguments&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;location&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Beijing&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;units&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;metric&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>请求带 <code>id</code>，响应使用同一 <code>id</code> 关联。Notification 没有 <code>id</code>，不期待响应。</p><h2 id="_7-能力与变化通知" tabindex="-1">7. 能力与变化通知 <a class="header-anchor" href="#_7-能力与变化通知" aria-label="Permalink to &quot;7. 能力与变化通知&quot;">​</a></h2><p>Server 可以声明 <code>tools.listChanged</code>、<code>resources.listChanged</code> 等能力。能力列表变化时发送通知，Client 再重新执行对应 <code>*/list</code>。</p><p>不要把连接建立时取得的工具列表永久缓存；也不要在未声明变化通知时假设会收到更新。</p><h2 id="_8-传输" tabindex="-1">8. 传输 <a class="header-anchor" href="#_8-传输" aria-label="Permalink to &quot;8. 传输&quot;">​</a></h2><h3 id="_8-1-stdio" tabindex="-1">8.1 stdio <a class="header-anchor" href="#_8-1-stdio" aria-label="Permalink to &quot;8.1 stdio&quot;">​</a></h3><p>Host 启动本地 Server 子进程，通过标准输入输出通信。适合本地工具和开发环境。</p><p>Server 的 stdout 必须只承载协议消息，普通日志应写 stderr，否则会破坏消息帧。</p><h3 id="_8-2-streamable-http" tabindex="-1">8.2 Streamable HTTP <a class="header-anchor" href="#_8-2-streamable-http" aria-label="Permalink to &quot;8.2 Streamable HTTP&quot;">​</a></h3><p>通过 HTTP POST 发送消息，可配合 SSE 实现服务端流式。适合远程、多客户端服务，并可使用标准 HTTP 认证。</p><p>旧 SSE 传输已经不是新集成首选。实现时必须以目标协议版本的正式规范为准。</p><h2 id="_9-状态与会话" tabindex="-1">9. 状态与会话 <a class="header-anchor" href="#_9-状态与会话" aria-label="Permalink to &quot;9. 状态与会话&quot;">​</a></h2><p>MCP 是能力交换协议，不应把隐式进程状态当成唯一业务状态。远程重连、负载均衡和客户端重试都可能改变会话假设。</p><p>需要跨调用状态时，应明确生命周期、恢复方式和状态句柄。不要让工具正确性依赖“恰好由同一进程处理下一次调用”。</p><h2 id="_10-安全边界" tabindex="-1">10. 安全边界 <a class="header-anchor" href="#_10-安全边界" aria-label="Permalink to &quot;10. 安全边界&quot;">​</a></h2><ol><li>Server 提供工具不等于用户被授权调用；</li><li>工具描述和返回内容都可能是不可信数据；</li><li>本地 stdio Server 具有宿主进程权限，应限制命令和文件范围；</li><li>远程 HTTP 使用认证、TLS、Origin 检查和最小 Scope；</li><li>高风险工具在 Host 或执行端要求确认；</li><li>日志、资源和工具结果需要脱敏；</li><li>不把来自一个 Server 的内容当作可覆盖 Host 指令的系统消息。</li></ol><h2 id="_11-mcp-不负责什么" tabindex="-1">11. MCP 不负责什么 <a class="header-anchor" href="#_11-mcp-不负责什么" aria-label="Permalink to &quot;11. MCP 不负责什么&quot;">​</a></h2><p>MCP 不定义：</p><ul><li>模型或 Agent 的推理策略；</li><li>工具选择质量；</li><li>业务权限和租户隔离；</li><li>工具幂等和事务；</li><li>上下文裁剪与记忆；</li><li>多 Agent 协作协议。</li></ul><p>跨 Agent 系统通信通常属于 A2A 等其他协议，不应与 MCP 工具和上下文交换混为一谈。</p><h2 id="_12-版本边界" tabindex="-1">12. 版本边界 <a class="header-anchor" href="#_12-版本边界" aria-label="Permalink to &quot;12. 版本边界&quot;">​</a></h2><p>本文以 2025-11-25 稳定规范为基线。Draft 中的实验变化不能当作稳定能力；例如 Tasks 在该稳定版本中仍属于实验能力。客户端和服务端必须通过初始化协商实际协议版本。</p><h2 id="_13-小结" tabindex="-1">13. 小结 <a class="header-anchor" href="#_13-小结" aria-label="Permalink to &quot;13. 小结&quot;">​</a></h2><p>MCP 由 Host、Client、Server 和两层协议组成，通过生命周期协商 Tools、Resources、Prompts 等能力。它解决互操作问题，但执行授权、业务正确性和 Agent 控制仍由应用负责。</p>`,62)])])}const u=s(n,[["render",l]]);export{k as __pageData,u as default};
